WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pl_q_min_wait'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '等待最少策略', 'kp-pl-q-min-wait', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "排队等待最少策略"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "让打水/理发最快的人排在最前面！这样后面所有人等待的时间总和才最小。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲打水 3 分钟，乙 5 分钟，丙 1 分钟。只有一个水龙头，怎么排队使三人打水加等待的总时间最少？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第一个人打水，后面所有人都要等他。所以第一个人的打水时间会被计算 N 次。必须让最短的时间被乘 N！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A需1分，B需2分，C需3分。求最少总时间？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "排序：A -> B -> C。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算A耗时：打水1分。对总体的贡献：自己1分+B等1分+C等1分 = 1×3=3分。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算B耗时：打水2分。对总体的贡献：自己2分+C等2分 = 2×2=4分。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算C耗时：打水3分。对总体贡献：3×1=3分。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "总计：3 + 4 + 3 = 10 分钟。"}]}]}]}]}$$ AS jsonb), NULL, '等待最少策略的核心考点与实战推导。', category_node.id, CAST('["数量关系", "等待最少策略"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pl_q_min_wait", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
